const raw = $input.item.json.body ?? $input.item.json;

const cleanStr = (v) => (typeof v === 'string' ? v.trim() : '');
const normalizeEmail = (v) => cleanStr(v).toLowerCase();
const normalizePhoneDigits = (v) => {
  const digits = cleanStr(v).replace(/\D/g, '');
  if (digits.length === 11 && digits.startsWith('1')) return digits.slice(1);
  return digits;
};

const channelRaw = cleanStr(raw.channel || raw.type || (raw.From || raw.from ? 'sms' : 'email')).toLowerCase();
const sourceChannel = channelRaw.includes('sms') || channelRaw.includes('text') || channelRaw.includes('phone')
  ? 'sms'
  : 'email';

const fromEmail = normalizeEmail(
  raw.from_email || raw.sender_email || raw.email || raw.from || ''
);
const fromPhoneRaw = cleanStr(
  raw.from_phone || raw.sender_phone || raw.phone || raw.From || ''
);
const fromPhoneDigits = normalizePhoneDigits(fromPhoneRaw);

const subjectLine = cleanStr(raw.subject || raw.subject_line || (sourceChannel === 'sms' ? 'Inbound SMS Reply' : 'Inbound Email Reply'));
const bodyText = cleanStr(
  raw.text || raw.body_text || raw.Body || raw.message || raw.snippet || ''
);
const replyExcerpt = bodyText.slice(0, 500);

const lowerBody = bodyText.toLowerCase();
const notFitPatterns = [
  /\bunsubscribe\b/i,
  /\bstop\b/i,
  /\bremove me\b/i,
  /\bnot interested\b/i,
  /\bno thanks\b/i,
  /\bwrong person\b/i,
  /\balready have an agency\b/i,
  /\bdo not contact\b/i
];
const notNowPatterns = [
  /\bnot right now\b/i,
  /\bnext quarter\b/i,
  /\bnext month\b/i,
  /\btoo busy\b/i,
  /\bswamped\b/i,
  /\breach out in\b/i,
  /\bcheck back\b/i,
  /\bbudget\b.*\b(tight|later|next year)\b/i
];

let outcome = 'replied_interested';
let replySentiment = 'positive';

if (notFitPatterns.some((rx) => rx.test(lowerBody))) {
  outcome = 'replied_not_fit';
  replySentiment = 'negative';
} else if (notNowPatterns.some((rx) => rx.test(lowerBody))) {
  outcome = 'replied_not_now';
  replySentiment = 'neutral';
}

const providerEventId = cleanStr(
  raw.event_id || raw.message_id || raw.MessageSid || raw.id || ''
);
const externalEventId = providerEventId
  ? `inbound_${sourceChannel}_${providerEventId}`
  : `inbound_${sourceChannel}_${fromPhoneDigits || fromEmail}_${replyExcerpt.length}_${cleanStr(raw.occurred_at || '').slice(0, 19)}`;

const occurredAt = cleanStr(raw.occurred_at || raw.timestamp || '') || new Date().toISOString();

return {
  json: {
    source_channel: sourceChannel,
    channel: 'inbound_reply',
    from_email: fromEmail,
    from_phone_raw: fromPhoneRaw,
    from_phone_digits: fromPhoneDigits,
    subject_line: subjectLine,
    message_summary: `Inbound ${sourceChannel.toUpperCase()} reply from ${fromEmail || fromPhoneRaw || 'unknown sender'}: "${replyExcerpt.slice(0, 140)}"`,
    outcome,
    reply_sentiment: replySentiment,
    reply_excerpt: replyExcerpt,
    external_event_id: externalEventId,
    occurred_at: occurredAt
  }
};
